(function(){if(!window.jQuery||!jQuery.fn.select2)return;jQuery(function(){var select=jQuery('.review-team-filter'),hint=jQuery('#review-team-hint');function updateHint(){var count=(select.val()||[]).length;hint.html(count?('已选择 <strong>'+count+'</strong> 个团队'):'可多选，未选择时查询全部团队');}select.select2({width:'100%',placeholder:'选择一个或多个团队',allowClear:true,closeOnSelect:false,language:{noResults:function(){return '没有找到团队';}}}).on('change',updateHint);updateHint();});})();
(function(){var form=document.getElementById('review-import-form');if(!form)return;var panel=document.getElementById('review-import-progress'),bar=document.getElementById('review-import-progress-bar'),percent=document.getElementById('review-import-progress-percent'),label=document.getElementById('review-import-progress-text'),result=document.getElementById('review-import-result'),submit=document.getElementById('review-import-submit'),timer=null;function show(value,title,detail,error){value=Math.max(0,Math.min(100,Math.round(value)));panel.style.display='block';bar.style.width=value+'%';percent.textContent=value+'%';label.textContent=title;result.textContent=detail||'';result.classList.toggle('is-error',!!error);bar.classList.toggle('progress-bar-danger',!!error);bar.classList.toggle('progress-bar-success',!error);}function message(xhr){try{var data=JSON.parse(xhr.responseText),errors=data.errors||{},items=[];Object.keys(errors).forEach(function(key){(errors[key]||[]).forEach(function(item){if(items.indexOf(item)<0)items.push(item);});});if(items.length)return '失败原因：\n'+items.join('\n');if(data.message)return '失败原因：'+data.message;}catch(e){}return xhr.status===413?'失败原因：上传文件过大。':'失败原因：导入请求失败（HTTP '+xhr.status+'）。';}form.addEventListener('submit',function(event){event.preventDefault();if(!form.reportValidity())return;if(!confirm('导入后会直接生成待审核记录，确认继续？'))return;submit.disabled=true;show(2,'正在上传文件','请勿关闭页面。',false);var xhr=new XMLHttpRequest(),current=42;xhr.open('POST',form.action,true);xhr.setRequestHeader('Accept','application/json');xhr.setRequestHeader('X-Requested-With','XMLHttpRequest');xhr.upload.onprogress=function(e){if(e.lengthComputable)show(Math.max(2,Math.round(e.loaded/e.total*40)),'正在上传文件','文件已上传 '+Math.round(e.loaded/e.total*100)+'%。',false);};xhr.upload.onload=function(){show(current,'正在解析并导入','正在校验数据、保存截图并生成审核记录……',false);timer=setInterval(function(){if(current<90){current+=2;show(current,'正在解析并导入','服务器正在处理，请勿关闭页面……',false);}},600);};xhr.onload=function(){if(timer)clearInterval(timer);if(xhr.status>=200&&xhr.status<300){var data=JSON.parse(xhr.responseText);show(100,'导入完成','成功导入 '+data.imported_count+' 条数据，生成 '+data.report_count+' 份待审核记录。',false);bar.classList.remove('active');setTimeout(function(){location.href=data.redirect_url;},1000);}else{show(100,'导入失败',message(xhr),true);bar.classList.remove('active');submit.disabled=false;}};xhr.onerror=function(){if(timer)clearInterval(timer);show(100,'导入失败','失败原因：网络连接异常。',true);submit.disabled=false;};xhr.send(new FormData(form));});})();
(function(){var select=document.getElementById('review-per-page');if(!select)return;select.addEventListener('change',function(){var url=new URL(window.location.href);url.searchParams.set('per_page',select.value);url.searchParams.set('page','1');window.location.href=url.toString();});})();
(function(){var form=document.getElementById('bulk-review-form'),all=document.getElementById('select-all-pending'),boxes=Array.prototype.slice.call(document.querySelectorAll('.report-checkbox')),count=document.getElementById('bulk-review-count'),action=document.getElementById('bulk-review-action'),rejectBox=document.getElementById('bulk-reject-box'),reason=document.getElementById('bulk-review-reason');if(!form)return;function selected(){return boxes.filter(function(box){return box.checked;});}function update(){var checked=selected().length;count.textContent='已选 '+checked+' 份';all.checked=boxes.length>0&&checked===boxes.length;all.indeterminate=checked>0&&checked<boxes.length;}function requireSelection(){if(selected().length)return true;window.alert('请至少选择一条待审核报表。');return false;}all.addEventListener('change',function(){boxes.forEach(function(box){box.checked=all.checked;});update();});boxes.forEach(function(box){box.addEventListener('change',update);});document.getElementById('bulk-approve').addEventListener('click',function(){if(!requireSelection())return;if(!window.confirm('确认将选中的 '+selected().length+' 份运营报表批量审核通过？'))return;action.value='approved';reason.value='';form.submit();});document.getElementById('bulk-reject').addEventListener('click',function(){if(!requireSelection())return;rejectBox.style.display='block';reason.focus();});document.getElementById('cancel-bulk-reject').addEventListener('click',function(){rejectBox.style.display='none';reason.value='';});document.getElementById('confirm-bulk-reject').addEventListener('click',function(){if(!requireSelection())return;if(!reason.value.trim()){window.alert('请输入审核不通过原因。');reason.focus();return;}if(!window.confirm('确认将选中的 '+selected().length+' 份运营报表批量审核不通过？'))return;action.value='rejected';form.submit();});update();})();
(function(){var form=document.getElementById('delete-report-form');if(!form)return;document.addEventListener('click',function(event){var button=event.target.closest('.js-delete-report');if(!button)return;var message='确定删除 '+button.dataset.operator+' 在 '+button.dataset.date+' 的广告费提报吗？\n\n无论当前审核状态如何都会删除，删除后该运营可以重新提交当天记录。';if(!window.confirm(message))return;button.disabled=true;form.action=button.dataset.url;form.submit();});})();
</script>
@endpush
